// SRD FR-03: (2/2) 计算最终得分

// 1. 从上一节点获取文章原始数据和Gemini的响应
const article = $input.item.json; // splitInBatches的输出
const geminiResponse = $('FR-03: (1/2) LLM评分').item.json.text; // Gemini的响应文本

// 2. 从Gemini响应中提取纯净的JSON字符串
const jsonRegex = /{[\s\S]*?}/;
const match = geminiResponse.match(jsonRegex);

if (!match) {
  throw new Error('在Gemini响应中未找到有效的JSON评分对象。');
}

const scores = JSON.parse(match[0]);

// 3. 计算加权分
const weighted_score = (scores.novelty_score * 0.3) + 
                       (scores.impact_score * 0.4) + 
                       (scores.clarity_score * 0.1) + 
                       (scores.depth_score * 0.2);

// 4. 计算平局决胜值
const word_count = article.word_count || 0; // 如果word_count不存在则默认为0
const tie_breaker_value = word_count * 0.00001;

// 5. 计算最终得分并保留两位小数
const final_score = (weighted_score + tie_breaker_value).toFixed(2);

// 6. 返回文章ID和最终得分，用于下一步数据库更新
return {
  id: article.id,
  ai_score: parseFloat(final_score)
};

// 将Top 5文章聚合成一个字符串，注入到最终的Prompt中

const topArticles = $input.all();

let aggregatedContent = '';

topArticles.forEach((item, index) => {
  const article = item.json;
  aggregatedContent += `
---
文章${index + 1}:
标题: ${article.title}
作者: ${article.author || '未知'}
来源URL: ${article.source_url || '无'}
内容: ${article.content.substring(0, 3000)}...
---
`;
});

return { aggregatedContent };

// 从Markdown全文中提取标题和导语

const markdown = $json.text;

// 提取标题 (第一行)
const title = markdown.split('\n')[0].replace(/^#+\s*/, '');

// 提取导语 (第一个'###'之前的内容，去掉标题)
const summaryEndIndex = markdown.indexOf('###');
const summary = markdown.substring(markdown.indexOf('\n') + 1, summaryEndIndex).trim();

// 返回用于数据库插入的对象
return {
  title: title,
  content: markdown,
  summary: summary,
  status: 'draft',
  is_selected: true
};
